more-student.code:
#include <stdio.h>
struct student { int rollno; char name[20]; int marks[5]; };
int main(void) {
    struct student s1;
    int i, sum = 0;
    float avg;
    if (scanf("%d%19s", &s1.rollno, s1.name) != 2) return 1;
    for (i = 0; i < 5; i++) {
        if (scanf("%d", &s1.marks[i]) != 1 || s1.marks[i] < 0 || s1.marks[i] > 100) return 1;
        sum += s1.marks[i];
    }
    avg = (float)sum / 5;
    printf("%d %s\n", s1.rollno, s1.name);
    for (i = 0; i < 5; i++) printf("%d%c", s1.marks[i], i == 4 ? '\n' : ' ');
    printf("Average: %.2f\n", avg);
    return 0;
}

extra-students.code:
#include <stdio.h>
struct student { int rollno; char name[20]; int marks[20]; };
int main(void) {
    struct student s[30];
    int n, m, i, j, sum;
    if (scanf("%d%d", &n, &m) != 2 || n < 1 || n > 30 || m < 1 || m > 20) return 1;
    for (i = 0; i < n; i++) {
        sum = 0;
        if (scanf("%d%19s", &s[i].rollno, s[i].name) != 2) return 1;
        for (j = 0; j < m; j++) {
            if (scanf("%d", &s[i].marks[j]) != 1 || s[i].marks[j] < 0 || s[i].marks[j] > 100) return 1;
            sum += s[i].marks[j];
        }
        printf("%d %s\n", s[i].rollno, s[i].name);
        for (j = 0; j < m; j++) printf("%d%c", s[i].marks[j], j == m - 1 ? '\n' : ' ');
        printf("Average: %.2f\n", (float)sum / m);
    }
    return 0;
}

