#include <stdio.h>
typedef struct complex { float r, m; } node;
node addcomplex(node c1, node c2) {
    node c3;
    c3.r = c1.r + c2.r; c3.m = c1.m + c2.m;
    return c3;
}
struct student { int marks; };
void addition(struct student *s2) { s2->marks += 10; }
int main(void) {
    node c1 = {1, 2}, c2 = {3, 4}, c3;
    struct student s1 = {75};
    c3 = addcomplex(c1, c2);
    printf("Complex sum: %.1f + %.1fi\n", c3.r, c3.m);
    addition(&s1);
    printf("Marks: %d\n", s1.marks);
    return 0;
}

