#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int n = 3, i, *p, *zeros, *tmp;
    p = malloc((size_t)n * sizeof *p);
    if (p == NULL) return 1;
    for (i = 0; i < n; i++) p[i] = (i + 1) * 10;
    zeros = calloc((size_t)n, sizeof *zeros);
    if (zeros == NULL) { free(p); return 1; }
    printf("calloc: %d %d %d\n", zeros[0], zeros[1], zeros[2]);
    tmp = realloc(p, 5 * sizeof *p);
    if (tmp == NULL) { free(zeros); free(p); return 1; }
    p = tmp;
    p[3] = 40; p[4] = 50;
    printf("Values:");
    for (i = 0; i < 5; i++) printf(" %d", p[i]);
    putchar('\n');
    free(zeros); free(p);
    return 0;
}

