u4-five-students.code:
#include <stdio.h>
struct student {
    int rollno;
    char name[20], address[100];
    int marks[3];
};
int main(void) {
    struct student s[5];
    int i, j, total;
    for (i = 0; i < 5; i++) {
        if (scanf("%d%19s%99s", &s[i].rollno, s[i].name, s[i].address) != 3) return 1;
        total = 0;
        for (j = 0; j < 3; j++) {
            if (scanf("%d", &s[i].marks[j]) != 1 || s[i].marks[j] < 0 || s[i].marks[j] > 100) return 1;
            total += s[i].marks[j];
        }
        printf("%d %s %s\n", s[i].rollno, s[i].name, s[i].address);
        printf("Marks: %d %d %d\n", s[i].marks[0], s[i].marks[1], s[i].marks[2]);
        printf("Total: %d\nPercentage: %.2f%%\n", total, total / 3.0);
    }
    return 0;
}

